page Home "/" {
  state count = 0
  state frames = 0
  state paused = false
  ref canvasEl
  ref balls = []
  ref raf

  fn makeBall() {
    return {
      x: 10 + Math.random() * 380,
      y: 10 + Math.random() * 280,
      vx: Math.random() * 6 - 3,
      vy: Math.random() * 6 - 3,
      r: 10
    }
  }

  fn reset() {
    balls = []
    for (let i = 0; i < 5; i++) {
      balls.push(makeBall())
    }
    count = balls.length
    frames = 0
    draw()
  }

  fn add() {
    balls.push(makeBall())
    count = balls.length
    draw()
  }

  fn step() {
    for b in balls {
      b.vy += 0.2
      b.x += b.vx
      b.y += b.vy
      if b.x < b.r {
        b.x = b.r
        b.vx = Math.abs(b.vx)
      }
      if b.x > 400 - b.r {
        b.x = 400 - b.r
        b.vx = -Math.abs(b.vx)
      }
      if b.y < b.r {
        b.y = b.r
        b.vy = Math.abs(b.vy)
      }
      if b.y > 300 - b.r {
        b.y = 300 - b.r
        b.vy = -Math.abs(b.vy)
      }
    }
    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let a = balls[i]
        let c = balls[j]
        let dx = c.x - a.x
        let dy = c.y - a.y
        let dist = Math.sqrt(dx * dx + dy * dy)
        let minD = a.r + c.r
        if dist < minD {
          let approaching = (c.vx - a.vx) * dx + (c.vy - a.vy) * dy < 0
          if approaching || dist == 0 {
            let tvx = a.vx
            let tvy = a.vy
            a.vx = c.vx
            a.vy = c.vy
            c.vx = tvx
            c.vy = tvy
          }
          if dist > 0 {
            let overlap = (minD - dist) / 2
            let nx = dx / dist
            let ny = dy / dist
            a.x -= nx * overlap
            a.y -= ny * overlap
            c.x += nx * overlap
            c.y += ny * overlap
          }
          for p in [a, c] {
            p.x = Math.min(Math.max(p.x, p.r), 400 - p.r)
            p.y = Math.min(Math.max(p.y, p.r), 300 - p.r)
          }
        }
      }
    }
  }

  fn draw() {
    if !canvasEl { return }
    let ctx = canvasEl.getContext("2d")
    ctx.clearRect(0, 0, 400, 300)
    ctx.fillStyle = "#f8fafc"
    ctx.fillRect(0, 0, 400, 300)
    ctx.fillStyle = "#2563eb"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn tick() {
    if !paused {
      step()
      draw()
      frames++
    }
    raf = requestAnimationFrame(tick)
  }

  mount {
    reset()
    raf = requestAnimationFrame(tick)
    cleanup { cancelAnimationFrame(raf) }
  }

  column gap=3 pad=4 align=start {
    canvas ref=canvasEl id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" primary -> add()
      button (paused ? "Reanudar" : "Pausar") -> paused = !paused
      button "Reiniciar" -> reset()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

const W = 400
const H = 300
const R = 10
const G = 0.2

fn randomBall(existing) {
  let b = null
  for (let tries = 0; tries < 50; tries++) {
    b = {
      x: R + Math.random() * (W - 2 * R),
      y: R + Math.random() * (H - 2 * R),
      vx: (Math.random() * 2 - 1) * 4,
      vy: (Math.random() * 2 - 1) * 4
    }
    let ok = true
    for o in existing {
      if Math.hypot(o.x - b.x, o.y - b.y) < 2 * R {
        ok = false
        break
      }
    }
    if ok {
      return b
    }
  }
  return b
}

fn physics(balls) {
  for b in balls {
    b.vy += G
    b.x += b.vx
    b.y += b.vy
    if b.x < R {
      b.x = R
      b.vx = Math.abs(b.vx)
    }
    if b.x > W - R {
      b.x = W - R
      b.vx = -Math.abs(b.vx)
    }
    if b.y < R {
      b.y = R
      b.vy = Math.abs(b.vy)
    }
    if b.y > H - R {
      b.y = H - R
      b.vy = -Math.abs(b.vy)
    }
  }
  for (let i = 0; i < balls.length; i++) {
    for (let j = i + 1; j < balls.length; j++) {
      let a = balls[i]
      let c = balls[j]
      let dx = c.x - a.x
      let dy = c.y - a.y
      let d = Math.hypot(dx, dy)
      if d < 2 * R {
        let nx = d > 0 ? dx / d : 1
        let ny = d > 0 ? dy / d : 0
        let approaching = (c.vx - a.vx) * nx + (c.vy - a.vy) * ny < 0
        if approaching {
          let tvx = a.vx
          let tvy = a.vy
          a.vx = c.vx
          a.vy = c.vy
          c.vx = tvx
          c.vy = tvy
        }
        let overlap = (2 * R - d) / 2
        a.x -= nx * overlap
        a.y -= ny * overlap
        c.x += nx * overlap
        c.y += ny * overlap
      }
    }
  }
  for b in balls {
    b.x = Math.min(W - R, Math.max(R, b.x))
    b.y = Math.min(H - R, Math.max(R, b.y))
  }
}

page Home "/" {
  ref box
  ref balls
  ref raf
  state paused = false
  state frames = 0
  state count = 0

  fn reset() {
    let list = []
    for (let i = 0; i < 5; i++) {
      list.push(randomBall(list))
    }
    balls = list
    count = list.length
    frames = 0
  }

  fn draw() {
    if !box {
      return
    }
    let ctx = box.getContext("2d")
    ctx.clearRect(0, 0, W, H)
    ctx.fillStyle = "#2563eb"
    for b in balls {
      ctx.beginPath()
      ctx.arc(b.x, b.y, R, 0, Math.PI * 2)
      ctx.fill()
    }
  }

  fn loop() {
    physics(balls)
    draw()
    frames++
    raf = requestAnimationFrame(loop)
  }

  fn add() {
    balls.push(randomBall(balls))
    count = balls.length
    if paused {
      draw()
    }
  }

  fn toggle() {
    if paused {
      paused = false
      raf = requestAnimationFrame(loop)
    } else {
      paused = true
      cancelAnimationFrame(raf)
    }
  }

  fn restart() {
    reset()
    draw()
  }

  mount {
    reset()
    raf = requestAnimationFrame(loop)
    cleanup {
      cancelAnimationFrame(raf)
    }
  }

  column gap=3 pad=4 {
    title "Simulación de pelotas"
    canvas ref=box id="sim" width=400 height=300 style="border: 1px solid #ccc"
    row gap=2 {
      button "Agregar" -> add()
      button (paused ? "Reanudar" : "Pausar") primary -> toggle()
      button "Reiniciar" -> restart()
    }
    text `Pelotas: ${count}`
    text `Cuadros: ${frames}`
  }
}

