// ───────────── Utilidades de formato ─────────────

fn formatoFecha(iso) {
  let [a, m, d] = iso.split("-")
  return `${d}/${m}/${a}`
}

fn formatoUSD(n) {
  let entero = String(Math.round(n))
  return "US$ " + entero.replace(/\B(?=(\d{3})+(?!\d))/g, ".")
}

fn iniciales(nombre) {
  return nombre.split(" ").filter(p => p != "").map(p => p[0].toUpperCase()).join("")
}

fn colorDe(nombre) {
  let h = 0
  for (let i = 0; i < nombre.length; i++) {
    h = (h * 31 + nombre.charCodeAt(i)) >>> 0
  }
  return `hsl(${h % 360}, 60%, 45%)`
}

